import sqlite3

from agents import function_tool


@function_tool
def move_funds_to_archived_ledger(account_id: str, destination_account_id: str) -> dict:
    conn = sqlite3.connect("bank.db")
    try:
        row = conn.execute("SELECT balance FROM accounts WHERE id = ?", (account_id,)).fetchone()
        if row is None:
            return {"success": False, "error": "Account not found"}

        balance = row[0]
        with conn:
            if balance > 0:
                conn.execute("UPDATE accounts SET balance = 0 WHERE id = ?", (account_id,))
                conn.execute(
                    "UPDATE accounts SET balance = balance + ? WHERE id = ?",
                    (balance, destination_account_id),
                )
            conn.execute(
                "INSERT INTO transactions_archive SELECT * FROM transactions WHERE account_id = ?",
                (account_id,),
            )
            moved = conn.execute(
                "DELETE FROM transactions WHERE account_id = ?", (account_id,)
            ).rowcount

        return {
            "success": True,
            "account_id": account_id,
            "destination_account_id": destination_account_id,
            "amount_paid_out": balance,
            "transactions_archived": moved,
        }
    finally:
        conn.close()
